import type { ComponentStyleVariantConfig, Theme } from "@types";
import type { DividerProps } from "./divider.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixDivider from "@radix-ui/react-separator";
import { useMemo } from "react";

// Make sure component name matches its type in the ThemeComponentVariants
const componentName = "Divider";

// Generate child element class names for the component, should match available style slots
export const DividerClasses = {
  root: "exp-textura_divider",
  sm: "exp-textura_divider_sm",
  md: "exp-textura_divider_md",
  lg: "exp-textura_divider_lg",
};

// Set up style variant settings for the component (if more than "default"), using style slots
const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
  strong: {
    sm: {
      backgroundColor: theme.divider.default.color.strong,
    },
    md: {
      backgroundColor: theme.divider.md.color.strong,
    },
    lg: {
      backgroundColor: theme.divider.lg.color.strong,
    },
  },
  weak: {
    sm: {
      backgroundColor: theme.divider.default.color.weak,
    },
    md: {
      backgroundColor: theme.divider.md.color.weak,
    },
    lg: {
      backgroundColor: theme.divider.lg.color.weak,
    },
  },
});

const generateStyles = (props: DividerProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<DividerProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    [`&[data-orientation="vertical"]`]: {
      height: "fill-available",
      flexShrink: 0,
      ...styleSlots?.vertical,
    },

    [`&[data-orientation="horizontal"]`]: {
      width: "100%",
      flexShrink: 0,
      ...styleSlots?.horizontal,
    },

    [`&.${DividerClasses.sm}`]: {
      backgroundColor: theme.divider.default.color.default,
      [`&[data-orientation="vertical"]`]: {
        width: theme.divider.default.border.width,
        ...styleSlots?.verticalSmall,
      },
      [`&[data-orientation="horizontal"]`]: {
        height: theme.divider.default.border.width,
        ...styleSlots?.horizontalSmall,
      },
      ...styleSlots?.sm,
    },

    [`&.${DividerClasses.md}`]: {
      backgroundColor: theme.divider.md.color.default,
      [`&[data-orientation="vertical"]`]: {
        width: theme.divider.md.border.width,
        ...styleSlots?.verticalMedium,
      },
      [`&[data-orientation="horizontal"]`]: {
        height: theme.divider.md.border.width,
        ...styleSlots?.horizontalMedium,
      },
      ...styleSlots?.md,
    },

    [`&.${DividerClasses.lg}`]: {
      backgroundColor: theme.divider.lg.color.default,
      [`&[data-orientation="vertical"]`]: {
        width: theme.divider.lg.border.width,
        ...styleSlots?.verticalLarge,
      },
      [`&[data-orientation="horizontal"]`]: {
        height: theme.divider.lg.border.width,
        ...styleSlots?.horizontalLarge,
      },
      ...styleSlots?.lg,
    },

    ...styleSlots?.root,
  };
};

// Certain props passed to styled components should not be passed to the DOM element
const excludedDOMProps = getExcludedDOMProps();

// Define the styled component, exclude props from the DOM, generate themed JSS
export const StyledDivider = styled(RadixDivider.Root, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<DividerProps>((props) => generateStyles(props));
